#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>
#include <bitset>
#include <cstring>
using namespace std;

const int INF = 0x3f3f3f3f;

struct Mat {
    vector<vector<int>> data;

    Mat(vector<vector<int>>& d) {
        swap(d, data);
    }

    Mat() = default;

    void operator*=(const Mat& o) {
        vector<vector<int>> res(
            data.size(),
            vector<int>(o.data[0].size(), INF)
        );

        for (size_t i = 0; i < data.size(); ++i) {
            for (size_t j = 0; j < o.data[0].size(); ++j) {
                for (size_t k = 0; k < o.data.size(); ++k) {
                    res[i][j] = min(res[i][j], data[i][k] + o.data[k][j]);
                }
            }
        }

        swap(data, res);
    }
};

ostream& operator<<(ostream& out, const Mat& mat) {
    out << "{\n";
    for (const auto& row : mat.data) {
        for (int value : row) {
            out << value << ' ';
        }
        out << '\n';
    }
    out << '}';
    return out;
}

int X, K, N, Q, jmp[9];
vector<vector<int>> oneStep;

struct Stone {
    int loc, val;

    bool operator<(const Stone& o) const {
        return loc < o.loc;
    }
} magic[25];

vector<int>& go(vector<int>& beginState, int stepCnt, vector<int>& res) {
    auto step = oneStep;
    Mat mat(step);

    Mat origin;
    origin.data.resize(1);
    swap(origin.data[0], beginState);

    for (int i = 0; (stepCnt >> i); ++i) {
        if ((stepCnt >> i) & 1) {
            origin *= mat;
        }
        mat *= mat;
    }

    swap(res, origin.data[0]);
    return res;
}

vector<int>& dp(vector<int>& lastState, int stepCnt,
                int stoneAfter[201], int stoneEffect[26]) {
    vector<vector<int>> table(
        stepCnt + 1,
        vector<int>(lastState.size(), INF)
    );

    for (size_t i = 0; i < lastState.size(); ++i) {
        table[0][i] = lastState[i];
    }

    for (int step = 0; step < stepCnt; ++step) {
        for (int cur = 1; cur < (1 << K); ++cur) {
            if (__builtin_popcount(static_cast<unsigned>(cur)) != X ||
                table[step][cur] == INF) {
                continue;
            }

            if (cur & 1) {
                for (int nb = 0; nb < K; ++nb) {
                    if (!((cur >> 1) & (1 << nb))) {
                        int nxt = (cur >> 1) | (1 << nb);
                        table[step + 1][nxt] = min(
                            table[step + 1][nxt],
                            table[step][cur] + jmp[nb + 1] +
                                stoneEffect[stoneAfter[nb + step + 1]]
                        );
                    }
                }
            } else {
                int nxt = cur >> 1;
                table[step + 1][nxt] =
                    min(table[step + 1][nxt], table[step][cur]);
            }
        }
    }

    for (size_t i = 0; i < lastState.size(); ++i) {
        lastState[i] = table[stepCnt][i];
    }

    return lastState;
}

