    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> X >> K >> N >> Q;

    for (int i = 1; i <= K; ++i) {
        cin >> jmp[i];
    }

    for (int i = 0; i < Q; ++i) {
        cin >> magic[i].loc >> magic[i].val;
    }

    sort(magic, magic + Q);

    oneStep.assign(1 << K, vector<int>(1 << K, INF));

    for (int cur = 1; cur < (1 << K); ++cur) {
        if (__builtin_popcount(static_cast<unsigned>(cur)) == X &&
            (cur & 1) == 1) {
            for (int nb = 0; nb < K; ++nb) {
                if (!((cur >> 1) & (1 << nb))) {
                    int nxt = (cur >> 1) | (1 << nb);
                    oneStep[cur][nxt] =
                        min(oneStep[cur][nxt], jmp[nb + 1]);
                }
            }
        } else if (__builtin_popcount(static_cast<unsigned>(cur)) == X) {
            oneStep[cur][cur >> 1] = 0;
        }
    }

    vector<int> res;
    vector<int> lastState(1 << K, INF);
    lastState[(1 << X) - 1] = 0;

    int stoneEffect[26] = {};
    for (int i = 0; i < Q; ++i) {
        stoneEffect[i + 1] = magic[i].val;
    }

    int curLoc = 0;

    for (int i = 0; i < Q;) {
        if (magic[i].loc - K - curLoc > 0) {
            res = go(lastState, magic[i].loc - K - curLoc, res);
            curLoc = magic[i].loc - K;
            swap(lastState, res);
        }

