        stoneAfter[K] = ++i;
        int stLoc = magic[i - 1].loc;

        while (i < Q && stLoc + K >= magic[i].loc) {
            stLoc = magic[i].loc;
            stoneAfter[stLoc - curLoc] = ++i;
        }

