            lastState, stLoc - curLoc, stoneAfter, stoneEffect
        );
        curLoc = stLoc;
    }

    res = go(lastState, N - curLoc - K, res);

    int ans = INF;
    for (int i = 0; i <= K - X; ++i) {
        ans = min(ans, res[((1 << X) - 1) << (K - X - i)]);
        swap(lastState, res);
        res = go(lastState, 1, res);
    }

    cout << ans << '\n';
    return 0;
}

